describe('Active Sessions Management', () => {
  beforeEach(() => {
    cy.visit('/profile/sessions');
  });

  it('should display all active sessions and allow logout of specific sessions', () => {
    // Intercept API call to fetch sessions
    cy.intercept('GET', '/api/user/sessions').as('getSessions');
    cy.wait('@getSessions');

    // Verify sessions are displayed
    cy.get('[data-testid="session-list"]').should('be.visible');
    cy.get('[data-testid="session-item"]').should('have.length.greaterThan', 0);

    // Verify session details are visible
    cy.get('[data-testid="session-item"]').first().within(() => {
      cy.get('[data-testid="session-user-email"]').should('contain', 'user@example.com');
      cy.get('[data-testid="session-device"]').should('contain', 'Chrome');
      cy.get('[data-testid="session-last-login"]').should('be.visible');
    });

    // Verify logout button exists for each session
    cy.get('[data-testid="session-item"]').each(($session) => {
      cy.wrap($session).find('[data-testid="logout-button"]').should('be.visible');
    });

    // Log out a specific session
    cy.get('[data-testid="session-item"]').eq(1).within(() => {
      cy.get('[data-testid="logout-button"]').click();
    });

    // Verify logout confirmation modal appears
    cy.get('[data-testid="logout-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-logout-button"]').should('contain', 'Confirm Logout');

    // Confirm logout
    cy.get('[data-testid="confirm-logout-button"]').click();

    // Verify success message
    cy.get('[data-testid="logout-success-message"]').should('be.visible');
    cy.get('[data-testid="logout-success-message"]').should('contain', 'Session logged out successfully');

    // Verify session is removed from list
    cy.get('[data-testid="session-item"]').should('have.length', 1);
  });

  it('should handle case with no active sessions', () => {
    // Intercept API call to fetch sessions with empty response
    cy.intercept('GET', '/api/user/sessions', {
      statusCode: 200,
      body: { sessions: [] }
    }).as('getEmptySessions');
    cy.wait('@getEmptySessions');

    // Verify empty state message is displayed
    cy.get('[data-testid="no-active-sessions-message"]').should('be.visible');
    cy.get('[data-testid="no-active-sessions-message"]').should('contain', 'You have no active sessions');

    // Verify session list container is empty
    cy.get('[data-testid="session-list"]').should('be.visible');
    cy.get('[data-testid="session-item"]').should('not.exist');

    // Verify logout button is not displayed when no sessions exist
    cy.get('[data-testid="logout-button"]').should('not.exist');
  });
});
